import test from 'node:test';import assert from 'node:assert/strict';
import {normalizeMachines,machineReady} from '../src/machines.js';
import {normalizeExpeditions,expeditionEnter,expeditionCell,expeditionTick,expeditionPath,expeditionChunkItems} from '../src/expeditions.js';
import {normalizeTrailMachines,trailAllows,trailPads,syncTrailMachines,trailMachineAction,trailMachineView,trailMachinePoses,trailMachineJournal} from '../src/trail-machines.js';
const setup=(mode='forest',type='rover')=>{const exp=normalizeExpeditions(),s=normalizeTrailMachines(),garage=normalizeMachines({models:[{id:'m1',type,color:'orange',parts:type==='helperbot'?{module:'sprayer'}:{}}]});expeditionEnter(exp,mode);return {exp,s,garage,act:a=>trailMachineAction(exp,s,garage,a)};};
test('only prepared compatible worlds accept complete machines; starter copies preserve current drafts',()=>{const {exp,s,garage,act}=setup();assert.ok(trailAllows(garage.models[0],'forest'));assert.ok(!trailAllows(garage.models[0],'ocean'));garage.drafts.rover={type:'rover',parts:{frame:'round'},color:'purple'};const old=JSON.stringify(garage.drafts);act({type:'starter',machineType:'helperbot'});assert.equal(JSON.stringify(garage.drafts),old);assert.equal(garage.models.length,2);assert.equal(garage.models[1].parts.module,'sprayer');assert.ok(machineReady(garage.models[1]));expeditionEnter(exp,'cave');exp.worlds.cave.y=4800;assert.deepEqual(trailPads(exp,'rover'),[]);});
test('deployed exact snapshots survive edits, moving, reload and packing while garage and own blocks remain',()=>{const {exp,s,garage,act}=setup('farm','helperbot');act({type:'place',modelId:'m1',pad:0});const p=s.placements[0];assert.equal(p.snapshot.color,'orange');garage.models[0].parts.module='gripper';garage.models[0].color='blue';act({type:'place',modelId:'m1',moveId:p.id,pad:1});assert.equal(s.placements[0].snapshot.parts.module,'sprayer');assert.equal(s.placements[0].snapshot.color,'orange');const saved=normalizeTrailMachines(JSON.parse(JSON.stringify(s)));assert.deepEqual(saved.placements,s.placements);const w=exp.worlds.farm;w.blocks['5,5']='block';const before=JSON.stringify(garage);act({type:'pack',id:p.id});assert.equal(s.placements.length,0);assert.equal(w.blocks['5,5'],'block');assert.equal(JSON.stringify(garage),before);});
test('bridge placement supplies a real walkable deck and reversible gap; one tap crosses it',()=>{const {exp,s,act}=setup('forest','bridge');act({type:'place',modelId:'m1',pad:1});const p=s.placements[0],w=exp.worlds.forest;w.x=p.x-100;w.y=p.y;w.fly=false;assert.ok(expeditionCell(w,'forest',p.x/40,p.y/40).platform);assert.equal(expeditionCell(w,'forest',p.x/40,p.y/40+1).type,'water');assert.ok(expeditionPath(w,'forest',{x:p.x+100,y:p.y}).length);act({type:'use',id:p.id});for(let i=0;i<150;i++)expeditionTick(exp,.05);assert.ok(Math.abs(w.x-(p.x+100))<45);assert.equal(w.y,p.y);act({type:'pack',id:p.id});assert.equal(Object.keys(w.deploymentCells).length,0);});
test('farm robots water nearby planted beds without accelerating growth or watering distant plants',()=>{const {exp,s,act}=setup('farm','helperbot');act({type:'place',modelId:'m1',pad:0});const p=s.placements[0],w=exp.worlds.farm,k=(p.x/40+3)+','+(p.y/40);w.plots[k]={seed:'bean',stage:0,watered:false,harvested:false};w.plots['999,999']={seed:'bean',stage:0,watered:false,harvested:false};act({type:'use',id:p.id});assert.equal(w.plots[k].watered,true);assert.equal(w.plots[k].stage,0);assert.equal(w.plots['999,999'].watered,false);expeditionEnter(exp,'forest');expeditionEnter(exp,'farm');assert.equal(w.plots[k].stage,1);assert.equal(w.plots[k].watered,false);assert.equal(trailMachineJournal(s,'experiments')[0].title,'My farm robot watered plants');});
test('rover surveys collect only nearby generated finds and repeat without duplicate rewards',()=>{const {exp,s,garage,act}=setup();const w=exp.worlds.forest,item=expeditionChunkItems(w,'forest',0).find(i=>i.type==='seed'&&i.y>1200);s.placements.push({id:'t1',mode:'forest',modelId:'m1',x:Math.round(item.x/40)*40,y:item.y,snapshot:structuredClone(garage.models[0]),used:false,running:false});const result=act({type:'use',id:'t1'});assert.ok(result.effect?.seed);const again=act({type:'use',id:'t1'});assert.equal(again.effect,null);assert.equal(w.found.length,1);assert.equal(s.history.length,1);});
test('habitats offer reversible rest and saved journal revisits; rendering remains bounded',()=>{const {exp,s,act}=setup('forest','habitat');act({type:'place',modelId:'m1',pad:0});const p=s.placements[0];assert.equal(act({type:'rest',id:p.id}).pause,true);assert.equal(act({type:'resume'}).pause,false);assert.equal(trailMachineJournal(s,'did')[0].trailPlacementId,p.id);assert.ok(trailMachinePoses(exp,s,0).length<=4);for(const o of trailMachinePoses(exp,s,0)){assert.ok(o.hitX>=160&&o.hitX<=840);assert.ok(o.hitY>=210&&o.hitY<=400);}assert.equal(trailMachineJournal(s,'found').length,0);});
test('normalization rejects corrupt snapshots and all menu pages fit native controls',()=>{const {exp,s,garage,act}=setup();act({type:'place',modelId:'m1',pad:0});const raw=JSON.parse(JSON.stringify(s));raw.placements.push({...raw.placements[0],id:'t2',snapshot:{type:'rocket',color:'blue',parts:{}}});assert.equal(normalizeTrailMachines(raw).placements.length,1);for(const route of ['home','starters','help','library:0','worlds:m1','pads:m1','placements:0','placed:t1','rest:t1'])assert.ok(trailMachineView(exp,s,garage,route).actions.length<=5,route);});
